import{_ as a,o as t,c as i,a3 as n}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Plugin Development","description":"Technical starting point for developers building ATLAS plugins.","frontmatter":{"title":"Plugin Development","description":"Technical starting point for developers building ATLAS plugins."},"headers":[],"relativePath":"en/projects/atlas-plugins/developers/index.md","filePath":"en/projects/atlas-plugins/developers/index.md","lastUpdated":1793123358000}'),l={name:"en/projects/atlas-plugins/developers/index.md"};function o(r,e,s,d,p,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="plugin-development" tabindex="-1">Plugin Development <a class="header-anchor" href="#plugin-development" aria-label="Permalink to &quot;Plugin Development&quot;">​</a></h1><p>This section follows the development path for standalone ATLAS plugins, from the starter project through manifests and Runtime to publishing. Plugin contracts are still evolving; check the current template and repository format before publishing.</p><h2 id="recommended-workflow" tabindex="-1">Recommended workflow <a class="header-anchor" href="#recommended-workflow" aria-label="Permalink to &quot;Recommended workflow&quot;">​</a></h2><ol><li>Create a repository from the <a href="./../plugin-template">official plugin template</a>.</li><li>Choose a unique, stable plugin ID and maintain the name, version, description, assets and required capabilities in the manifest.</li><li>Develop the plugin UI independently first. The current template includes a small HTML/CSS/JavaScript example page.</li><li>Build the package and catalog with <code>npm run build</code>, then validate them with <code>npm run check</code>.</li><li>Test the catalog through the ATLAS demo repository or Administration. Increment the plugin version for every published change.</li></ol><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><ul><li><a href="./compatibility">Versions and compatibility</a>: release rules, verified boundaries, backups and data migration.</li><li><a href="./manifest">Manifest and capabilities</a>: metadata, IDs, versions, assets and declarations.</li><li><a href="./runtime">Runtime and lifecycle</a>: the Runtime plugin contract and activation, deactivation and cleanup.</li><li><a href="./publishing">Build, validate and publish</a>: package builder, catalog, GitHub Actions and release checklist.</li><li><a href="./../plugin-template">Plugin Template</a>: step-by-step guide to the GitHub starter repository.</li><li><a href="./../repository-format">Repository Format</a>: catalog fields and installable package format.</li></ul><h2 id="security-boundaries" tabindex="-1">Security boundaries <a class="header-anchor" href="#security-boundaries" aria-label="Permalink to &quot;Security boundaries&quot;">​</a></h2><p>Declare only capabilities your plugin actually uses. A declaration documents the plugin&#39;s intent; it is not a sandbox and does not automatically grant access to Home Assistant or Atlas internals. Do not request credentials in plugin files or publish tokens and API keys.</p><p>The App server installs validated repository and imported packages in persistent plugin storage and serves static web files under <code>/plugin-assets/&lt;slug&gt;/</code>. Opening them runs their JavaScript in the browser; arbitrary Node modules or Runtime hooks are not automatically registered. Installation is not a sandbox: review package contents and browser code before opening.</p>',9)])])}const m=a(l,[["render",o]]);export{h as __pageData,m as default};
